func (r *QueryResolver) MyHosDailyLogs(ctx context.Context, startDate string, endDate string) ([]*gqlmodel.WorkerHosDailyLog, error) {
	authCtx, err := r.RequireAuth(ctx)
	if err != nil {
		return nil, err
	}
	for _, date := range []string{startDate, endDate} {
		if _, parseErr := time.Parse("2006-01-02", date); parseErr != nil {
			return nil, errortypes.NewValidationError(
				"startDate",
				errortypes.ErrInvalid,
				"Dates must use the YYYY-MM-DD format",
			)
		}
	}
	wrk, err := r.DriverPortalService.ResolveWorker(ctx, resolvercore.TenantInfo(authCtx))
	if err != nil {
		return nil, err
	}
	days, err := r.TelematicsService.GetWorkerHOSDailyLogs(
		ctx,
		resolvercore.TenantInfo(authCtx),
		wrk.ID,
		startDate,
		endDate,
	)
	if err != nil {
		return nil, err
	}
	out := make([]*gqlmodel.WorkerHosDailyLog, 0, len(days))
	for _, day := range days {
		out = append(out, telematicsmapping.MapWorkerHOSDailyLog(day))
	}
	return out, nil
}

func (r *QueryResolver) MyHosViolations(ctx context.Context, since *int) ([]*gqlmodel.WorkerHosViolation, error) {
	authCtx, err := r.RequireAuth(ctx)
	if err != nil {
		return nil, err
	}
	wrk, err := r.DriverPortalService.ResolveWorker(ctx, resolvercore.TenantInfo(authCtx))
	if err != nil {
		return nil, err
	}
	sinceAt := int64(0)
	if since != nil && *since > 0 {
		sinceAt = int64(*since)
	}
	violations, err := r.TelematicsService.ListWorkerHOSViolations(
		ctx,
		resolvercore.TenantInfo(authCtx),
		wrk.ID,
		sinceAt,
		0,
	)
	if err != nil {
		return nil, err
	}
	out := make([]*gqlmodel.WorkerHosViolation, 0, len(violations))
	for _, violation := range violations {
		out = append(out, telematicsmapping.MapWorkerHOSViolation(violation))
	}
	return out, nil
}

func (r *QueryResolver) MyNotifications(ctx context.Context, input gqlmodel.DataTableConnectionInput, filter *gqlmodel.NotificationFilterInput) (*gqlmodel.NotificationConnection, error) {
	authCtx, err := r.RequireAuth(ctx)
	if err != nil {
		return nil, err
	}
	ti := resolvercore.TenantInfo(authCtx)
	if _, err = r.DriverPortalService.ResolveWorker(ctx, ti); err != nil {
		return nil, err
	}
	tableInput, err := gqlconnection.DataTableConnectionFromGraphQL(ctx, &input, ti)
	if err != nil {
		return nil, err
	}
	req := &notificationports.ListNotificationConnectionRequest{
		Filter:       tableInput.Filter,
		Cursor:       tableInput.Cursor,
		PersonalOnly: true,
	}
	notificationmapping.ApplyNotificationFilter(req, filter)
	result, err := r.NotificationService.ListConnection(ctx, req)
	if err != nil {
		return nil, err
	}
	return notificationmapping.NotificationConnectionToModel(result)
}

func (r *QueryResolver) MyNotificationUnreadCount(ctx context.Context) (int, error) {
	authCtx, err := r.RequireAuth(ctx)
	if err != nil {
		return 0, err
	}
	ti := resolvercore.TenantInfo(authCtx)
	if _, err = r.DriverPortalService.ResolveWorker(ctx, ti); err != nil {
		return 0, err
	}
	count, err := r.NotificationService.CountUnread(ctx, authCtx.UserID, ti, true)
	if err != nil {
		return 0, err
	}
	return int(count), nil
}

